import{_ as n,o as s,c as t,ag as i}from"./chunks/framework.BpFM782D.js";const g=JSON.parse('{"title":"spec-review","description":"","frontmatter":{},"headers":[],"relativePath":"commands/ccg-spec-review.md","filePath":"commands/ccg-spec-review.md","lastUpdated":null}'),a={name:"commands/ccg-spec-review.md"};function o(l,e,p,c,r,u){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="spec-review" tabindex="-1">spec-review <a class="header-anchor" href="#spec-review" aria-label="Permalink to &quot;spec-review&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>spec-review</td></tr><tr><td>說明</td><td>双模型交叉审查（独立工具，随时可用）</td></tr><tr><td>系列</td><td>CCG</td></tr><tr><td>來源檔案</td><td><code>commands/ccg/spec-review.md</code></td></tr></tbody></table><hr><p>&lt;!-- CCG:SPEC:REVIEW:START --&gt; <strong>Core Philosophy</strong></p><ul><li>Dual-model cross-validation catches blind spots single-model review would miss.</li><li>Critical findings SHOULD be addressed before proceeding.</li><li>Review validates implementation against spec constraints and code quality.</li><li>This is an independent review tool—can be used anytime, not tied to archive workflow.</li></ul><p><strong>Guardrails</strong></p><ul><li><strong>MANDATORY</strong>: Both Codex AND Gemini must complete review before synthesis.</li><li>Review scope is strictly limited to the proposal&#39;s changes—no scope creep.</li><li>Refer to <code>openspec/config.yaml</code> for project conventions when reviewing OpenSpec proposals.</li></ul><p><strong>Steps</strong></p><ol><li><p><strong>Select Proposal</strong></p><ul><li>Run <code>openspec list --json</code> to display Active Changes.</li><li>Confirm with user which proposal ID to review.</li><li>Run <code>openspec status --change &quot;&amp;lt;proposal_id&gt;&quot; --json</code> to load spec and tasks.</li></ul></li><li><p><strong>Collect Implementation Artifacts</strong></p><ul><li>Identify all files modified by this proposal.</li><li>Use <code>git diff</code> to get change summary.</li><li>Load relevant spec constraints and PBT properties from <code>openspec/changes/&amp;lt;id&gt;/specs/</code>.</li></ul></li><li><p><strong>Multi-Model Review (PARALLEL)</strong></p><ul><li><strong>CRITICAL</strong>: You MUST launch BOTH Codex AND Gemini in a SINGLE message with TWO Bash tool calls.</li><li><strong>DO NOT</strong> call one model first and wait. Launch BOTH simultaneously with <code>run_in_background: true</code>.</li><li><strong>工作目录</strong>：<code>&amp;#123;&amp;#123;WORKDIR&amp;#125;&amp;#125;</code> 替换为目标工作目录的绝对路径。如果用户通过 <code>/add-dir</code> 添加了多个工作区，先确定任务相关的工作区。</li></ul><p><strong>Step 3.1</strong>: In ONE message, make TWO parallel Bash calls:</p><p><strong>FIRST Bash call (Codex)</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bash({</span></span>
<span class="line"><span>  command: &quot;/Users/ericcai/.claude/bin/codeagent-wrapper --backend codex - \\&quot;&amp;#123;&amp;#123;WORKDIR&amp;#125;&amp;#125;\\&quot; &lt;&lt;&#39;EOF&#39;\\nReview proposal &amp;lt;proposal_id&gt; implementation:\\n\\n## Codex Review Dimensions\\n1. **Spec Compliance**: Verify ALL constraints from spec are satisfied\\n2. **PBT Properties**: Check invariants, idempotency, bounds are correctly implemented\\n3. **Logic Correctness**: Edge cases, error handling, algorithm correctness\\n4. **Backend Security**: Injection vulnerabilities, auth checks, input validation\\n5. **Regression Risk**: Interface compatibility, type safety, breaking changes\\n\\n## Output Format (JSON)\\n{\\n  \\&quot;findings\\&quot;: [\\n    {\\n      \\&quot;severity\\&quot;: \\&quot;Critical|Warning|Info\\&quot;,\\n      \\&quot;dimension\\&quot;: \\&quot;spec_compliance|pbt|logic|security|regression\\&quot;,\\n      \\&quot;file\\&quot;: \\&quot;path/to/file.ts\\&quot;,\\n      \\&quot;line\\&quot;: 42,\\n      \\&quot;description\\&quot;: \\&quot;What is wrong\\&quot;,\\n      \\&quot;constraint_violated\\&quot;: \\&quot;Constraint ID from spec (if applicable)\\&quot;,\\n      \\&quot;fix_suggestion\\&quot;: \\&quot;How to fix\\&quot;\\n    }\\n  ],\\n  \\&quot;passed_checks\\&quot;: [\\&quot;List of verified constraints/properties\\&quot;],\\n  \\&quot;summary\\&quot;: \\&quot;Overall assessment\\&quot;\\n}\\nEOF&quot;,</span></span>
<span class="line"><span>  run_in_background: true,</span></span>
<span class="line"><span>  timeout: 300000,</span></span>
<span class="line"><span>  description: &quot;Codex: backend/logic review&quot;</span></span>
<span class="line"><span>})</span></span></code></pre></div><p><strong>SECOND Bash call (Gemini) - IN THE SAME MESSAGE</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bash({</span></span>
<span class="line"><span>  command: &quot;/Users/ericcai/.claude/bin/codeagent-wrapper --backend gemini - \\&quot;&amp;#123;&amp;#123;WORKDIR&amp;#125;&amp;#125;\\&quot; &lt;&lt;&#39;EOF&#39;\\nReview proposal &amp;lt;proposal_id&gt; implementation:\\n\\n## Gemini Review Dimensions\\n1. **Pattern Consistency**: Naming conventions, code style, project patterns\\n2. **Maintainability**: Readability, complexity, documentation adequacy\\n3. **Integration Risk**: Dependency changes, cross-module impacts\\n4. **Frontend Security**: XSS, CSRF, sensitive data exposure\\n5. **Spec Alignment**: Implementation matches spec intent (not just letter)\\n\\n## Output Format (JSON)\\n{\\n  \\&quot;findings\\&quot;: [\\n    {\\n      \\&quot;severity\\&quot;: \\&quot;Critical|Warning|Info\\&quot;,\\n      \\&quot;dimension\\&quot;: \\&quot;patterns|maintainability|integration|security|alignment\\&quot;,\\n      \\&quot;file\\&quot;: \\&quot;path/to/file.ts\\&quot;,\\n      \\&quot;line\\&quot;: 42,\\n      \\&quot;description\\&quot;: \\&quot;What is wrong\\&quot;,\\n      \\&quot;spec_reference\\&quot;: \\&quot;Spec section (if applicable)\\&quot;,\\n      \\&quot;fix_suggestion\\&quot;: \\&quot;How to fix\\&quot;\\n    }\\n  ],\\n  \\&quot;passed_checks\\&quot;: [\\&quot;List of verified aspects\\&quot;],\\n  \\&quot;summary\\&quot;: \\&quot;Overall assessment\\&quot;\\n}\\nEOF&quot;,</span></span>
<span class="line"><span>  run_in_background: true,</span></span>
<span class="line"><span>  timeout: 300000,</span></span>
<span class="line"><span>  description: &quot;Gemini: patterns/integration review&quot;</span></span>
<span class="line"><span>})</span></span></code></pre></div><p><strong>Step 3.2</strong>: After BOTH Bash calls return task IDs, wait for results with TWO TaskOutput calls:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TaskOutput({ task_id: &quot;&amp;lt;codex_task_id&gt;&quot;, block: true, timeout: 600000 })</span></span>
<span class="line"><span>TaskOutput({ task_id: &quot;&amp;lt;gemini_task_id&gt;&quot;, block: true, timeout: 600000 })</span></span></code></pre></div></li><li><p><strong>Synthesize Findings</strong></p><ul><li>Merge findings from both models.</li><li>Deduplicate overlapping issues.</li><li>Classify by severity: <ul><li><strong>Critical</strong>: Spec violation, security vulnerability, breaking change → MUST fix</li><li><strong>Warning</strong>: Pattern deviation, maintainability concern → SHOULD fix</li><li><strong>Info</strong>: Minor improvement suggestion → MAY fix</li></ul></li></ul></li><li><p><strong>Present Review Report</strong></p><ul><li>Display findings grouped by severity:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Review Report: &amp;lt;proposal_id&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Critical (X issues) - MUST FIX</span></span>
<span class="line"><span>- [ ] [SPEC] file.ts:42 - Constraint X violated: description</span></span>
<span class="line"><span>- [ ] [SEC] api.ts:15 - SQL injection vulnerability</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Warning (Y issues) - SHOULD FIX</span></span>
<span class="line"><span>- [ ] [PATTERN] utils.ts:88 - Inconsistent naming convention</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Info (Z issues) - MAY FIX</span></span>
<span class="line"><span>- [ ] [MAINT] helper.ts:20 - Consider extracting to separate function</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Passed Checks</span></span>
<span class="line"><span>- ✅ PBT: Idempotency property verified</span></span>
<span class="line"><span>- ✅ Security: No XSS vulnerabilities found</span></span></code></pre></div></li><li><p><strong>Decision Gate</strong></p><ul><li><p><strong>If Critical &gt; 0</strong>:</p><ul><li>Present findings to user.</li><li>Ask: &quot;Fix now or return to <code>/ccg:spec-impl</code> to address?&quot;</li><li>Do NOT allow archiving.</li></ul></li><li><p><strong>If Critical = 0</strong>:</p><ul><li>Ask user: &quot;All critical checks passed. Proceed to archive?&quot;</li><li>If Warning &gt; 0, recommend addressing before archive.</li></ul></li></ul></li><li><p><strong>Optional: Inline Fix Mode</strong></p><ul><li>If user chooses &quot;Fix now&quot; for Critical issues: <ul><li>Route each fix to appropriate model (backend→Codex, frontend→Gemini).</li><li>Apply fix using unified diff patch pattern.</li><li>Re-run affected review dimension.</li><li>Repeat until Critical = 0.</li></ul></li></ul></li><li><p><strong>Context Checkpoint</strong></p><ul><li>Report current context usage.</li><li>If approaching 80K tokens, suggest: &quot;Run <code>/clear</code> and continue with <code>/ccg:spec-review</code> or <code>/ccg:spec-impl</code>&quot;</li></ul></li></ol><p><strong>Exit Criteria</strong> Review is complete when:</p><ul><li>[ ] Both Codex and Gemini reviews completed</li><li>[ ] All findings synthesized and classified</li><li>[ ] Zero Critical issues remain (fixed or user-acknowledged)</li><li>[ ] User decision captured (archive / return to impl / defer)</li></ul><p><strong>Reference</strong></p><ul><li>View proposal: <code>openspec status --change &quot;&amp;lt;id&gt;&quot; --json</code></li><li>Check spec constraints: <code>rg -n &quot;CONSTRAINT:|MUST|INVARIANT:&quot; openspec/changes/&amp;lt;id&gt;/specs/</code></li><li>View implementation diff: <code>git diff</code></li><li>Archive (after passing): <code>/ccg:spec-impl</code> → Step 10 &lt;!-- CCG:SPEC:REVIEW:END --&gt;</li></ul>`,13)])])}const m=n(a,[["render",o]]);export{g as __pageData,m as default};
